Пример на симуляции
Вот симулятор той самой ситуации, где угадывание происходит случайным образом. Каждое подглядывание на ползунке ниже — это одна честно доигранная колода из 25 карт: после окончания одной колоды лаборатория смотрит на накопленный итог и решает, продолжать или нет.
Вопрос такой: если подглядывать за этим итогом несколько раз по ходу серии и выбирать первый стат значимый результат, как часто вы поймаете ложное доказательство телепатии?
Смотрите симуляцию ниже 👇


Code
viewof numLooks = Inputs.range([1, 100], {value: 5, step: 1, label: "Сколько раз подглядываем за накопленным результатом"})









Code
simulatePeeking = function(numLooks, nSims = 4000, stepsPerLook = 25) {
  const boundary = 1.96; // граница для alpha = 5%, двусторонний тест
  // один "взгляд" = одна колода из 25 карт Зенера (stepsPerLook = 25 угадываний)
  // приращение между взглядами генерируем сразу как гауссовский шум N(0, stepsPerLook)
  // (Box-Muller) — это предел суммы stepsPerLook честных монеток по CLT, без искажения
  // от дискретной решётки ±1 (при малом stepsPerLook дискретные шаги сами по себе
  // слегка завышают долю ложных срабатываний из-за эффекта чётности).
  // На результат (долю ложных срабатываний) величина stepsPerLook не влияет —
  // при гауссовских приращениях z-путь инвариантен к масштабу шага (Brownian scaling),
  // важно только число взглядов K. Проверено симуляцией: stepsPerLook=25 и 100 дают
  // одинаковые цифры в пределах шума Monte Carlo.
  const sd = Math.sqrt(stepsPerLook);
  const randNormal = function() {
    const u1 = Math.random(), u2 = Math.random();
    return sd * Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
  };
  let falsePositives = 0;
  const paths = [];
  for (let s = 0; s &lt; nSims; s++) {
    let cum = 0;
    let crossed = false;
    const path = [{look: 0, z: 0, series: s}];
    for (let look = 1; look &lt;= numLooks; look++) {
      cum += randNormal(); // никакой телепатии — чистый случайный шум со средним 0
      const n = look * stepsPerLook;
      const z = cum / Math.sqrt(n);
      path.push({look, z, series: s});
      if (Math.abs(z) &gt; boundary) crossed = true;
    }
    if (crossed) falsePositives++;
    if (s &lt; 35) paths.push(path); // для графика берём только часть траекторий
  }
  return {rate: falsePositives / nSims, paths: paths.flat()};
}









