function pnorm(x) {
  const ax = Math.abs(x) / Math.SQRT2
  const t  = 1 / (1 + 0.3275911 * ax)
  const poly = t * (0.254829592
               + t * (-0.284496736
               + t * ( 1.421413741
               + t * (-1.453152027
               + t *   1.061405429))))
  const erfc = poly * Math.exp(-ax * ax)
  return x &gt;= 0 ? 1 - erfc / 2 : erfc / 2
}

// Квантиль стандартного нормального (бисекция, 60 итераций)
function qnorm(p) {
  let lo = -8, hi = 8
  for (let i = 0; i &lt; 60; i++) {
    const m = (lo + hi) / 2
    pnorm(m) &lt; p ? (lo = m) : (hi = m)
  }
  return (lo + hi) / 2
}

// Генератор N(0,1) (Box–Muller)
function randn() {
  return Math.sqrt(-2 * Math.log(Math.random()))
       * Math.cos(2 * Math.PI * Math.random())
}

// FWER для n тестов через разложение Холецкого (поддерживает любые ρ, в т.ч. отрицательные).
// Equicorrelated Σ валидна при ρ &gt; −1/(n−1); при нарушении возвращает NaN.
function sim_fwer(n, alpha, rho, n_sims) {
  if (n === 1) {
    let hits = 0
    const zc = qnorm(1 - alpha / 2)
    for (let i = 0; i &lt; n_sims; i++) if (Math.abs(randn()) &gt; zc) hits++
    return hits / n_sims
  }
  if (rho &lt;= -1 / (n - 1)) return NaN

  const z_crit = qnorm(1 - alpha / 2)

  // Нижняя треугольная матрица Холецкого L: L·Lᵀ = Σ(ρ)
  const L = Array.from({length: n}, () =&gt; new Float64Array(n))
  for (let i = 0; i &lt; n; i++) {
    for (let j = 0; j &lt;= i; j++) {
      let s = 0
      for (let k = 0; k &lt; j; k++) s += L[i][k] * L[j][k]
      L[i][j] = i === j ? Math.sqrt(1 - s) : (rho - s) / L[j][j]
    }
  }

  let hits = 0
  for (let sim = 0; sim &lt; n_sims; sim++) {
    const eps = Array.from({length: n}, randn)
    let any = false
    for (let i = 0; i &lt; n; i++) {
      let z = 0
      for (let k = 0; k &lt;= i; k++) z += L[i][k] * eps[k]
      if (Math.abs(z) &gt; z_crit) { any = true; break }
    }
    if (any) hits++
  }
  return hits / n_sims
}
































R-код
sim_data = {
  run_btn  // пересчёт при нажатии кнопки
  // для отрицательных ρ матрица валидна только при n ≤ floor(−1/ρ)
  const n_limit = rho &lt; 0 ? Math.min(max_n, Math.floor(-1 / rho)) : max_n
  const rows = []
  for (let n = 1; n &lt;= n_limit; n++) {
    rows.push({
      n,
      sim:    sim_fwer(n, alpha, rho, n_sims_inp),
      theory: 1 - Math.pow(1 - alpha, n)
    })
  }
  return rows
}









