Интерактивная симуляция
Настройте параметры ниже и нажмите «Запустить». Симуляция многократно генерирует пары выборок из генеральных совокупностей с заданными параметрами и считает для каждого теста, в какой доле случаев была отклонена H0 (p-value &lt; α).

Параметры


Code
// Кастомный селектор сценариев, сгруппированный в два блока:
// H₀ верна (A/A — ошибка I рода) и H₀ неверна (A/B — мощность).
viewof scenario = {
  const groups = {
    "H₀ верна — ошибка I рода (A/A)": [
      "Сценарий 1: равные N и SD",
      "Сценарий 2: равные N, разные SD",
      "Сценарий 3: разные N, разные SD",
      "Сценарий 4: экспоненциальное, N, SD равны"
    ],
    "H₀ неверна — мощность (A/B)": [
      "Сценарий 5: есть эффект (Δ &gt; 0), равные n и SD",
      "Сценарий 6: выбросы (логнормальное)",
      "Сценарий 7: разные SD"
    ]
  };
  const initial = "Сценарий 1: равные N и SD";

  const root = document.createElement("form");
  root.onsubmit = e =&gt; e.preventDefault();
  root.style.cssText = "display:flex; gap:32px; flex-wrap:wrap;";

  let num = 0; // сквозной номер сценария 1..7 для якорей #scenario-N
  Object.entries(groups).forEach(([title, opts]) =&gt; {
    const col = document.createElement("div");
    const h = document.createElement("div");
    h.textContent = title;
    h.style.cssText = "font-weight:600; font-size:13px; margin-bottom:8px; color:#333;";
    col.append(h);
    opts.forEach(opt =&gt; {
      num += 1;
      const row = document.createElement("div");
      row.style.cssText = "display:flex; align-items:center; gap:8px; margin-bottom:5px; white-space:nowrap;";

      const label = document.createElement("label");
      label.style.cssText = "display:flex; align-items:center; gap:8px; font-size:14px; cursor:pointer;";
      const input = document.createElement("input");
      input.type = "radio";
      input.name = "scenario-choice";
      input.checked = (opt === initial);
      input.style.accentColor = "#4a90d9";
      input.addEventListener("change", () =&gt; {
        root.value = opt;
        root.dispatchEvent(new CustomEvent("input", { bubbles: true }));
      });
      label.append(input, document.createTextNode(opt));

      // ссылка к разбору этого сценария в тексте
      const link = document.createElement("a");
      link.href = `#scenario-${num}`;
      link.textContent = "↓ разбор";
      link.title = "Перейти к разбору сценария в тексте";
      link.style.cssText = "font-size:12px; color:#4a90d9; text-decoration:none; white-space:nowrap;";

      row.append(label, link);
      col.append(row);
    });
    root.append(col);
  });

  root.value = initial;
  return root;
}









