// ── Основная симуляция ──
simResult = {
  const { n1, n2, sd1, sd2, delta_mean, alpha, n_sim, distrib } = simConfig;
  const pSt = [], pWe = [], pMW = [], pBM = [];

  for (let i = 0; i &lt; n_sim; i++) {
    const a = generateSample(n1, 0, sd1, distrib);
    const b = generateSample(n2, delta_mean, sd2, distrib);
    pSt.push(pStudent(a, b));
    pWe.push(pWelch(a, b));
    pMW.push(pMannWhitney(a, b));
    pBM.push(pBrunnerMunzel(a, b));
  }

  const rateSt = pSt.filter(p =&gt; p &lt; alpha).length / n_sim;
  const rateWe = pWe.filter(p =&gt; p &lt; alpha).length / n_sim;
  const rateMW = pMW.filter(p =&gt; p &lt; alpha).length / n_sim;
  const rateBM = pBM.filter(p =&gt; p &lt; alpha).length / n_sim;

  return { pSt, pWe, pMW, pBM, rateSt, rateWe, rateMW, rateBM, alpha, delta_mean };
}









